const LEGACY_KEY='market-structure-lab:v1',KEY='market-structure-lab:v2',PREF_KEY='market-structure-lab:prefs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const blank=()=>({id:null,instrument:'',timeframe:'1H',session:'Nueva York',bias:'Neutral',hypothesis:'',confidence:50,setupName:'',entry:'',stop:'',target:'',result:'Pendiente',notes:'',actualR:'',execution:'Sin evaluar',lesson:'',image:'',annotations:[],checks:[],createdAt:null,updatedAt:null});
let store={draft:blank(),history:[]},state=store.draft,activeTool='select',toastTimer,zoneDraft=null,prefs={accountSize:'',riskPercent:'1',dailyLimit:'3'};

function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function persist(){store.draft=state;localStorage.setItem(KEY,JSON.stringify(store));$('#saveState').innerHTML='<i></i> Guardado local'}
function load(){try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.draft)store={draft:{...blank(),...saved.draft},history:Array.isArray(saved.history)?saved.history:[]};else{const old=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');if(old)store.draft={...blank(),...old}};prefs={...prefs,...JSON.parse(localStorage.getItem(PREF_KEY)||'{}')}}catch{}state=store.draft;['accountSize','riskPercent','dailyLimit'].forEach(k=>$('#'+k).value=prefs[k]);update()}
function rr(){const e=Number(state.entry),s=Number(state.stop),t=Number(state.target);if(!Number.isFinite(e)||!Number.isFinite(s)||!Number.isFinite(t)||e===s||!state.entry||!state.stop||!state.target)return null;const risk=Math.abs(e-s),reward=Math.abs(t-e);return {risk,reward,ratio:reward/risk,valid:(s<e&&t>e)||(s>e&&t<e)}}
function updateRR(){const data=rr(),badge=$('#rrBadge'),help=$('#rrHelp'),risk=$('#riskBar'),reward=$('#rewardBar');if(!data){badge.textContent='R:R —';help.textContent='Completá los tres precios para calcular el riesgo/beneficio.';risk.style.opacity=.25;reward.style.opacity=.25;updateRisk();return}badge.textContent=`R:R 1:${data.ratio.toFixed(2)}`;help.textContent=data.valid?`Riesgo ${data.risk.toLocaleString()} · potencial ${data.reward.toLocaleString()}`:'Revisá el orden de entrada, stop y objetivo.';badge.style.color=data.valid?'var(--lime)':'var(--orange)';risk.style.opacity=1;reward.style.opacity=1;const pct=Math.min(80,Math.max(20,data.ratio/(1+data.ratio)*100));risk.style.width=(100-pct)+'%';reward.style.width=pct+'%';updateRisk()}
function money(value){return Number.isFinite(value)?new Intl.NumberFormat('es-AR',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(value):'—'}
function updateRisk(){const capital=Number(prefs.accountSize),riskPct=Number(prefs.riskPercent),dailyPct=Number(prefs.dailyLimit),entry=Number(state.entry),stop=Number(state.stop),distance=Math.abs(entry-stop),amount=capital*riskPct/100,ready=capital>0&&riskPct>0&&distance>0,position=ready?amount/distance:NaN;$('#riskAmount').textContent=capital>0&&riskPct>0?money(amount):'—';$('#dailyLoss').textContent=capital>0&&dailyPct>0?money(capital*dailyPct/100):'—';$('#positionSize').textContent=Number.isFinite(position)?position.toLocaleString('es-AR',{maximumFractionDigits:6})+' u.':'—';const msg=$('#riskMessage');msg.classList.toggle('warning',riskPct>2||dailyPct>5);msg.textContent=riskPct>2?'Advertencia: el riesgo por operación supera el 2% del capital.':dailyPct>5?'Advertencia: el límite diario supera el 5% del capital.':ready?`Con una distancia de stop de ${distance.toLocaleString('es-AR')}, esta posición arriesga ${money(amount)}.`:'Usá la entrada y el stop del plan de operación para calcular la posición.'}
function update(){
  ['instrument','timeframe','session','hypothesis','confidence','setupName','entry','stop','target','result','notes','actualR','execution','lesson'].forEach(key=>{const el=$('#'+key);if(el)el.value=state[key]??''});
  $('#confidenceOutput').value=state.confidence+'%';$$('[data-bias]').forEach(b=>b.classList.toggle('active',b.dataset.bias===state.bias));
  $$('#checklist input').forEach(c=>c.checked=state.checks.includes(c.value));$('#confirmationCount').textContent=state.checks.length;$('#checkProgress').textContent=`${state.checks.length} / 5`;$('#annotationCount').textContent=state.annotations.length;
  $('#chartTitle').textContent=state.image?`${state.instrument||'Instrumento'} · ${state.timeframe}`:'Gráfico sin cargar';const img=$('#chartImage'),zone=$('#uploadZone');img.style.display=state.image?'block':'none';zone.style.display=state.image?'none':'flex';if(state.image)img.src=state.image;renderAnnotations();updateRR();renderHistory();renderAnalytics();renderWeeklyReport();
}
function bind(id,key,event='input'){ $(id).addEventListener(event,e=>{state[key]=e.target.value;if(key==='confidence')$('#confidenceOutput').value=e.target.value+'%';if(['instrument','timeframe'].includes(key))$('#chartTitle').textContent=state.image?`${state.instrument||'Instrumento'} · ${state.timeframe}`:'Gráfico sin cargar';if(['entry','stop','target'].includes(key))updateRR();persist()})}
['instrument','hypothesis','confidence','setupName','entry','stop','target','notes','actualR','lesson'].forEach(k=>bind('#'+k,k));['timeframe','session','result','execution'].forEach(k=>bind('#'+k,k,'change'));
$$('[data-bias]').forEach(btn=>btn.addEventListener('click',()=>{state.bias=btn.dataset.bias;update();persist()}));
$$('#checklist input').forEach(c=>c.addEventListener('change',()=>{state.checks=$$('#checklist input:checked').map(x=>x.value);update();persist()}));

function processImage(file){if(!file||!file.type.startsWith('image/'))return toast('Elegí una imagen válida');if(file.size>4_000_000)return toast('La imagen debe pesar menos de 4 MB');const reader=new FileReader();reader.onload=()=>{state.image=reader.result;state.annotations=[];update();persist();toast('Gráfico cargado')};reader.readAsDataURL(file)}
$('#chartUpload').addEventListener('change',e=>processImage(e.target.files[0]));const zone=$('#uploadZone');['dragenter','dragover'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.add('dragging')}));['dragleave','drop'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.remove('dragging')}));zone.addEventListener('drop',e=>processImage(e.dataTransfer.files[0]));document.addEventListener('paste',e=>{const file=[...e.clipboardData.files].find(f=>f.type.startsWith('image/'));if(file)processImage(file)});
$$('[data-tool]').forEach(btn=>btn.addEventListener('click',()=>{activeTool=btn.dataset.tool;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b===btn));$('#canvasHint').textContent=activeTool==='select'?'Arrastrá las zonas para moverlas, usá el control para redimensionar o hacé doble clic para eliminar.':['supply','demand'].includes(activeTool)?'Arrastrá sobre el gráfico para dibujar la zona.':'Hacé clic sobre el gráfico para agregar la marca.'}));
$('#canvasWrap').addEventListener('click',e=>{if(!state.image||activeTool==='select'||['supply','demand'].includes(activeTool)||e.target.closest('.annotation'))return;const rect=e.currentTarget.getBoundingClientRect(),x=((e.clientX-rect.left)/rect.width)*100,y=((e.clientY-rect.top)/rect.height)*100;let label={bos:'BOS',choch:'CHOCH',liquidity:'LIQUIDEZ',poi:'POI',note:'NOTA'}[activeTool];if(activeTool==='note'){const text=prompt('Texto de la nota:');if(!text)return;label=text.slice(0,36)}state.annotations.push({id:uid(),type:activeTool,label,x,y});update();persist()});
const canvas=$('#canvasWrap');canvas.addEventListener('pointerdown',e=>{if(!state.image||!['supply','demand'].includes(activeTool)||e.target.closest('.annotation'))return;e.preventDefault();const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*100,y=(e.clientY-rect.top)/rect.height*100,el=document.createElement('div');el.className='annotation zone';el.dataset.type=activeTool;el.style.left=x+'%';el.style.top=y+'%';el.innerHTML=`<span class="zone-label">${activeTool.toUpperCase()}</span>`;$('#annotations').appendChild(el);zoneDraft={type:activeTool,startX:x,startY:y,x,y,width:0,height:0,el,rect}});canvas.addEventListener('pointermove',e=>{if(!zoneDraft)return;const x=Math.max(0,Math.min(100,(e.clientX-zoneDraft.rect.left)/zoneDraft.rect.width*100)),y=Math.max(0,Math.min(100,(e.clientY-zoneDraft.rect.top)/zoneDraft.rect.height*100));zoneDraft.x=Math.min(zoneDraft.startX,x);zoneDraft.y=Math.min(zoneDraft.startY,y);zoneDraft.width=Math.abs(x-zoneDraft.startX);zoneDraft.height=Math.abs(y-zoneDraft.startY);Object.assign(zoneDraft.el.style,{left:zoneDraft.x+'%',top:zoneDraft.y+'%',width:zoneDraft.width+'%',height:zoneDraft.height+'%'})});window.addEventListener('pointerup',()=>{if(!zoneDraft)return;if(zoneDraft.width>=2&&zoneDraft.height>=2)state.annotations.push({id:uid(),type:zoneDraft.type,label:zoneDraft.type.toUpperCase(),x:zoneDraft.x,y:zoneDraft.y,width:zoneDraft.width,height:zoneDraft.height});zoneDraft=null;update();persist()});
function bindZoneEdit(el,a){el.addEventListener('pointerdown',e=>{if(activeTool!=='select')return;e.preventDefault();e.stopPropagation();const root=$('#canvasWrap').getBoundingClientRect(),startX=e.clientX,startY=e.clientY,original={x:a.x,y:a.y,width:a.width||15,height:a.height||10},resize=e.target.classList.contains('resize-handle');const move=ev=>{const dx=(ev.clientX-startX)/root.width*100,dy=(ev.clientY-startY)/root.height*100;if(resize){a.width=Math.max(2,Math.min(100-original.x,original.width+dx));a.height=Math.max(2,Math.min(100-original.y,original.height+dy))}else{a.x=Math.max(0,Math.min(100-original.width,original.x+dx));a.y=Math.max(0,Math.min(100-original.height,original.y+dy))}Object.assign(el.style,{left:a.x+'%',top:a.y+'%',width:a.width+'%',height:a.height+'%'})};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);persist()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)});el.addEventListener('dblclick',e=>{if(activeTool!=='select')return;e.stopPropagation();state.annotations=state.annotations.filter(x=>x.id!==a.id);update();persist()})}
function renderAnnotations(){const root=$('#annotations');root.innerHTML='';state.annotations.forEach(a=>{if(['supply','demand'].includes(a.type)){const el=document.createElement('div');el.className='annotation zone';el.dataset.type=a.type;Object.assign(el.style,{left:a.x+'%',top:a.y+'%',width:(a.width||15)+'%',height:(a.height||10)+'%'});el.innerHTML=`<span class="zone-label">${a.type.toUpperCase()}</span><i class="resize-handle"></i>`;bindZoneEdit(el,a);root.appendChild(el);return}const el=document.createElement('button');el.className='annotation';el.dataset.type=a.type;el.style.left=a.x+'%';el.style.top=a.y+'%';el.textContent=a.label;el.title='Clic para eliminar';el.addEventListener('click',e=>{e.stopPropagation();if(activeTool==='select'){state.annotations=state.annotations.filter(x=>x.id!==a.id);update();persist()}});root.appendChild(el)})}
$('#clearAnnotations').addEventListener('click',()=>{if(!state.annotations.length)return;state.annotations=[];update();persist();toast('Anotaciones eliminadas')});

function archive(){const now=new Date().toISOString(),data=JSON.parse(JSON.stringify(state));if(state.id){const index=store.history.findIndex(x=>x.id===state.id);data.updatedAt=now;if(index>=0)store.history[index]=data;else store.history.unshift(data);toast('Análisis actualizado')}else{data.id=uid();data.createdAt=now;data.updatedAt=now;store.history.unshift(data);state={...data};store.draft=state;toast('Análisis guardado en el historial')}persist();update()}
function loadHistory(id){const found=store.history.find(x=>x.id===id);if(!found)return;state=JSON.parse(JSON.stringify(found));store.draft=state;update();persist();window.scrollTo({top:0,behavior:'smooth'});toast('Análisis abierto')}
function duplicateHistory(id){const found=store.history.find(x=>x.id===id);if(!found)return;state={...JSON.parse(JSON.stringify(found)),id:null,createdAt:null,updatedAt:null,setupName:(found.setupName||'Setup')+' · copia'};store.draft=state;update();persist();window.scrollTo({top:0,behavior:'smooth'});toast('Copia lista para editar')}
function deleteHistory(id){if(!confirm('¿Eliminar este análisis del historial?'))return;store.history=store.history.filter(x=>x.id!==id);if(state.id===id)state=blank();store.draft=state;persist();update();toast('Análisis eliminado')}
function esc(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function renderHistory(){const query=($('#historySearch')?.value||'').trim().toLowerCase(),result=$('#historyResult')?.value||'';const list=store.history.filter(x=>(!result||x.result===result)&&(!query||`${x.instrument} ${x.setupName} ${x.timeframe}`.toLowerCase().includes(query)));$('#historyEmpty').style.display=list.length?'none':'block';const root=$('#historyList');root.innerHTML=list.map(x=>{const r=(()=>{const e=Number(x.entry),s=Number(x.stop),t=Number(x.target);return e&&s&&t&&e!==s?Math.abs(t-e)/Math.abs(e-s):null})();const date=new Date(x.updatedAt||x.createdAt||Date.now()).toLocaleDateString('es-AR',{day:'2-digit',month:'short',year:'2-digit'});return `<article class="history-card"><div class="history-date">${date}</div><div class="history-main"><strong>${esc(x.instrument||'Sin instrumento')}</strong><span>${esc(x.setupName||'Sin nombre')} · ${esc(x.timeframe)}</span></div><div class="history-metric"><small>R:R</small><strong>${r?'1:'+r.toFixed(2):'—'}</strong></div><span class="result-pill" data-result="${esc(x.result)}">${esc(x.result)}</span><div class="history-actions"><button data-action="open" data-id="${x.id}">Abrir</button><button data-action="copy" data-id="${x.id}">Duplicar</button><button class="delete" data-action="delete" data-id="${x.id}" aria-label="Eliminar análisis">×</button></div></article>`}).join('')}
function renderAnalytics(){
  const all=store.history,closed=all.filter(x=>['Ganadora','Perdedora','Break even'].includes(x.result)),wins=closed.filter(x=>x.result==='Ganadora'),rated=all.filter(x=>x.actualR!==''&&Number.isFinite(Number(x.actualR))),planned=all.filter(x=>x.execution&&x.execution!=='Sin evaluar'),disciplined=planned.filter(x=>x.execution==='Según plan');
  $('#metricTrades').textContent=all.length;$('#metricClosed').textContent=`${closed.length} cerrada${closed.length===1?'':'s'}`;$('#metricWinRate').textContent=closed.length?Math.round(wins.length/closed.length*100)+'%':'—';$('#metricAvgR').textContent=rated.length?(rated.reduce((sum,x)=>sum+Number(x.actualR),0)/rated.length).toFixed(2)+'R':'—';$('#metricDiscipline').textContent=planned.length?Math.round(disciplined.length/planned.length*100)+'%':'—';
  const sessions=['Londres','Nueva York','Asia'];$('#sessionStats').innerHTML=sessions.map(name=>{const rows=all.filter(x=>x.session===name),done=rows.filter(x=>['Ganadora','Perdedora','Break even'].includes(x.result)),rate=done.length?Math.round(done.filter(x=>x.result==='Ganadora').length/done.length*100):0;return `<div class="bar-row"><label>${name}</label><div class="bar-track"><i style="width:${rate}%"></i></div><span>${rows.length} · ${done.length?rate+'%':'—'}</span></div>`}).join('');
  const groups={};all.forEach(x=>{const key=(x.setupName||'Sin nombre').trim();groups[key]??=[];groups[key].push(x)});const setups=Object.entries(groups).map(([name,rows])=>{const done=rows.filter(x=>['Ganadora','Perdedora','Break even'].includes(x.result));return {name,count:rows.length,rate:done.length?Math.round(done.filter(x=>x.result==='Ganadora').length/done.length*100):null}}).sort((a,b)=>(b.rate??-1)-(a.rate??-1)||b.count-a.count).slice(0,4);$('#setupStats').innerHTML=setups.length?setups.map(x=>`<div class="setup-row"><strong>${esc(x.name)}</strong><span>${x.rate===null?'—':x.rate+'%'}</span><small>${x.count} trade${x.count===1?'':'s'}</small></div>`).join(''):'<p class="empty-stat">Los setups aparecerán cuando guardes tus análisis.</p>';
  let insight='Guardá algunas operaciones para descubrir patrones.';if(closed.length>=3){const best=sessions.map(name=>{const rows=closed.filter(x=>x.session===name);return {name,count:rows.length,rate:rows.length?rows.filter(x=>x.result==='Ganadora').length/rows.length:-1}}).sort((a,b)=>b.rate-a.rate)[0];insight=best.count?`${best.name} es tu sesión con mayor acierto: ${Math.round(best.rate*100)}% en ${best.count} operación${best.count===1?'':'es'}.`:`Ya tenés ${closed.length} operaciones cerradas. Completá la sesión para encontrar patrones.`}else if(all.length)insight=`Tenés ${all.length} análisis guardado${all.length===1?'':'s'}. Con 3 operaciones cerradas empezarán a aparecer patrones.`;$('#insightText').textContent=insight;
}
function weeklyData(){const end=new Date(),start=new Date(end);start.setDate(end.getDate()-6);start.setHours(0,0,0,0);const rows=store.history.filter(x=>new Date(x.updatedAt||x.createdAt||0)>=start),closed=rows.filter(x=>['Ganadora','Perdedora','Break even'].includes(x.result)),wins=closed.filter(x=>x.result==='Ganadora').length,rated=rows.filter(x=>x.actualR!==''&&Number.isFinite(Number(x.actualR))),netR=rated.reduce((sum,x)=>sum+Number(x.actualR),0);return {start,end,rows,closed,wins,winRate:closed.length?Math.round(wins/closed.length*100):null,netR,rated}}
function weeklyMarkdown(data=weeklyData()){const date=d=>d.toLocaleDateString('es-AR',{day:'2-digit',month:'short',year:'numeric'}),lines=[`# Market Structure Lab — Revisión semanal`,``,`**Período:** ${date(data.start)} — ${date(data.end)}`,``,`## Resumen`,``,`- Operaciones registradas: ${data.rows.length}`,'- Operaciones cerradas: '+data.closed.length,`- Win rate: ${data.winRate===null?'Sin muestra':data.winRate+'%'}`,`- Resultado neto: ${data.rated.length?data.netR.toFixed(2)+'R':'Sin datos'}`,``,`## Operaciones`,``,`| Fecha | Instrumento | Setup | Sesión | Resultado | R | Ejecución |`,`|---|---|---|---|---:|---:|---|`];data.rows.forEach(x=>lines.push(`| ${date(new Date(x.updatedAt||x.createdAt))} | ${x.instrument||'—'} | ${x.setupName||'—'} | ${x.session||'—'} | ${x.result||'—'} | ${x.actualR!==''?x.actualR:'—'} | ${x.execution||'—'} |`));const lessons=data.rows.filter(x=>x.lesson?.trim());lines.push(``,`## Aprendizajes`,``,...(lessons.length?lessons.map(x=>`- **${x.instrument||x.setupName||'Operación'}:** ${x.lesson.trim()}`):['- No se registraron aprendizajes esta semana.']),``,`---`,`Generado con Market Structure Lab. Herramienta educativa; no constituye asesoramiento financiero.`);return lines.join('\n')}
function renderWeeklyReport(){const data=weeklyData(),date=d=>d.toLocaleDateString('es-AR',{day:'2-digit',month:'short'});$('#reportPeriod').textContent=`${date(data.start)} — ${date(data.end)}`;$('#reportTrades').textContent=data.rows.length;$('#reportWinRate').textContent=data.winRate===null?'—':data.winRate+'%';$('#reportNetR').textContent=data.rated.length?`${data.netR>=0?'+':''}${data.netR.toFixed(2)}R`:'—'}
function downloadText(name,textValue,type='text/plain'){const blob=new Blob([textValue],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function weeklyPrintHtml(){const data=weeklyData(),date=d=>d.toLocaleDateString('es-AR',{day:'2-digit',month:'short',year:'numeric'}),rows=data.rows.map(x=>`<tr><td>${date(new Date(x.updatedAt||x.createdAt))}</td><td>${esc(x.instrument||'—')}</td><td>${esc(x.setupName||'—')}</td><td>${esc(x.session||'—')}</td><td>${esc(x.result||'—')}</td><td>${x.actualR!==''?esc(x.actualR)+'R':'—'}</td></tr>`).join('')||'<tr><td colspan="6">Sin operaciones en este período.</td></tr>',lessons=data.rows.filter(x=>x.lesson?.trim()).map(x=>`<li><strong>${esc(x.instrument||x.setupName||'Operación')}:</strong> ${esc(x.lesson)}</li>`).join('')||'<li>Sin aprendizajes registrados.</li>';return `<!doctype html><html><head><meta charset="utf-8"><title>Revisión semanal</title><style>@page{margin:18mm}body{font-family:Arial,sans-serif;color:#172019}h1{font-family:Georgia,serif;font-size:30px;margin-bottom:4px}.period{color:#667068}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:24px 0}.metrics div{border:1px solid #ccd4cd;border-radius:8px;padding:14px}.metrics span{display:block;font-size:9px;text-transform:uppercase;color:#667068}.metrics strong{display:block;font-family:Georgia,serif;font-size:25px;margin-top:6px}table{width:100%;border-collapse:collapse;font-size:10px}th,td{border-bottom:1px solid #dde2de;text-align:left;padding:8px 5px}th{font-size:8px;text-transform:uppercase;color:#667068}h2{font-family:Georgia,serif;margin-top:28px}li{margin:8px 0;line-height:1.45}.note{margin-top:32px;font-size:8px;color:#667068}</style></head><body><h1>Market Structure Lab</h1><p class="period">Revisión semanal · ${date(data.start)} — ${date(data.end)}</p><div class="metrics"><div><span>Operaciones</span><strong>${data.rows.length}</strong></div><div><span>Win rate</span><strong>${data.winRate===null?'—':data.winRate+'%'}</strong></div><div><span>R neta</span><strong>${data.rated.length?data.netR.toFixed(2)+'R':'—'}</strong></div></div><h2>Operaciones</h2><table><thead><tr><th>Fecha</th><th>Instrumento</th><th>Setup</th><th>Sesión</th><th>Resultado</th><th>R</th></tr></thead><tbody>${rows}</tbody></table><h2>Aprendizajes</h2><ul>${lessons}</ul><p class="note">Herramienta educativa. No constituye asesoramiento financiero.</p></body></html>`}
$('#historyList').addEventListener('click',e=>{const btn=e.target.closest('button[data-action]');if(!btn)return;({open:loadHistory,copy:duplicateHistory,delete:deleteHistory}[btn.dataset.action])(btn.dataset.id)});$('#historySearch').addEventListener('input',renderHistory);$('#historyResult').addEventListener('change',renderHistory);$('#saveAnalysis').addEventListener('click',archive);
$('#exportButton').addEventListener('click',()=>{const payload={version:2,...store};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`market-structure-lab-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Bitácora exportada')});
$('#exportMarkdown').addEventListener('click',()=>{downloadText(`revision-semanal-${new Date().toISOString().slice(0,10)}.md`,weeklyMarkdown(),'text/markdown');toast('Informe Markdown descargado')});
$('#exportPdf').addEventListener('click',()=>{const win=window.open('','_blank');if(!win)return toast('El navegador bloqueó la ventana de impresión');win.document.open();win.document.write(weeklyPrintHtml());win.document.close();win.focus();setTimeout(()=>win.print(),250)});
$('#importButton').addEventListener('click',()=>$('#importInput').click());$('#importInput').addEventListener('change',e=>{const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(data.draft&&Array.isArray(data.history))store={draft:{...blank(),...data.draft},history:data.history};else store={draft:{...blank(),...data},history:[]};state=store.draft;update();persist();toast('Bitácora importada')}catch{toast('El archivo no es válido')}};if(e.target.files[0])reader.readAsText(e.target.files[0])});
$('#newAnalysis').addEventListener('click',()=>{if(!confirm('¿Crear un análisis nuevo? El borrador actual se reemplazará.'))return;state=blank();store.draft=state;update();persist();toast('Nuevo análisis listo')});
['accountSize','riskPercent','dailyLimit'].forEach(key=>$('#'+key).addEventListener('input',e=>{prefs[key]=e.target.value;localStorage.setItem(PREF_KEY,JSON.stringify(prefs));updateRisk()}));
load();
